// ===== 1) Junta os dados que vieram do Merge =====
const itens = $input.all().map(i => i.json);

let clientes = [];
let investimentos = [];

for (const it of itens) {
  if (it.body?.clientes) clientes = it.body.clientes;
  if (it.clientes) clientes = it.clientes;
  if (it.investimentos) investimentos = it.investimentos;
}

// ===== 2) Funções auxiliares =====
const paraNumero = (txt) =>
  Number(String(txt).replace(/[^\d,.-]/g, "").replace(/\./g, "").replace(",", ".")) || 0;

const brl = (n) =>
  Number(n).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const normaliza = (s) =>
  String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

// Tom da mensagem por perfil (Etapa 4 do projeto)
const focoPerfil = {
  conservador: "Seu foco é renda fixa e segurança do patrimônio.",
  moderado: "A ideia é um mix equilibrado entre renda fixa e variável.",
  arrojado: "Aqui a ênfase é em ações e maior potencial de retorno."
};

// ===== 3) Recomendação por cliente =====
const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;
  const saldoNum = paraNumero(c.saldo);

  // Produtos do mesmo perfil, do menor para o maior mínimo
  const doPerfil = investimentos
    .filter(i => normaliza(i.perfil) === normaliza(perfil))
    .map(i => ({ ...i, minimo: Number(i.minimo) || 0 }))
    .sort((a, b) => a.minimo - b.minimo);

  // Produtos que o saldo já cobre
  const cabem = doPerfil.filter(i => i.minimo <= saldoNum);

  let escolhido, motivo, mensagens;

  if (doPerfil.length === 0) {
    escolhido = null;
    motivo = "sem_produto_para_perfil";
    mensagens = [
      `Olá ${nome}! No momento não temos produtos cadastrados para o perfil ${perfil}. Em breve entraremos em contato.`
    ];
  } else if (cabem.length > 0) {
    escolhido = cabem[cabem.length - 1]; // o de maior mínimo que o saldo cobre
    motivo = "saldo_ok";
    const p = escolhido;
    mensagens = [
      `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${p.produto}** (mínimo ${brl(p.minimo)}). Com seu saldo atual (${brl(saldoNum)}), você já consegue investir. Rentabilidade: ${p.rentabilidade}.`,
      `Oi ${nome}! Recomendação para perfil ${perfil}: **${p.produto}** (mínimo ${brl(p.minimo)}). Seu saldo (${brl(saldoNum)}) já atende o mínimo. Rentabilidade: ${p.rentabilidade}.`,
      `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${p.produto}** (mínimo ${brl(p.minimo)}). Você tem ${brl(saldoNum)}, então dá pra aplicar. Rentabilidade: ${p.rentabilidade}.`
    ];
  } else {
    escolhido = doPerfil[0]; // o de menor mínimo, que é o mais próximo
    motivo = "saldo_insuficiente";
    const p = escolhido;
    const falta = p.minimo - saldoNum;
    mensagens = [
      `Olá ${nome}! Para o seu perfil (${perfil}), a opção de entrada é **${p.produto}** (mínimo ${brl(p.minimo)}). Seu saldo atual é ${brl(saldoNum)}, faltam ${brl(falta)} para investir. Rentabilidade: ${p.rentabilidade}.`,
      `Oi ${nome}! Recomendação para perfil ${perfil}: **${p.produto}** (mínimo ${brl(p.minimo)}). Com mais ${brl(falta)} você atinge o mínimo. Rentabilidade: ${p.rentabilidade}.`,
      `${nome}, indo direto ao ponto: o produto ideal para o perfil ${perfil} é **${p.produto}**, mas o mínimo é ${brl(p.minimo)} e você tem ${brl(saldoNum)}. Faltam ${brl(falta)}.`
    ];
  }

  // Acrescenta o tom do perfil em todas as mensagens
  const foco = focoPerfil[normaliza(perfil)] || "";
  mensagens = mensagens.map(m => `${m} ${foco}`.trim());

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// ===== 4) Saída =====
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

// Pega o CSV como texto vindo do HTTP Request
const entrada = $input.first().json;
const csvRaw = entrada.data ?? entrada.body ?? entrada;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

// Quebra em linhas e remove linhas vazias
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

// Detecta o separador (; ou ,) pela linha de cabeçalho
const sep = lines[0].includes(";") ? ";" : ",";

const headers = lines[0].split(sep).map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(sep).map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // Normaliza "minimo" para número (aceita 1000, 1.000,50, R$ 500,00)
  if ("minimo" in obj) {
    let v = String(obj.minimo).replace(/[^\d,.-]/g, "");
    if (v.includes(",")) v = v.replace(/\./g, "").replace(",", ".");
    obj.minimo = Number(v) || 0;
  }

  return obj;
});

return [{ json: { investimentos } }];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

