// Dados preparados antes da IA (mesma ordem dos itens)
// >>> o nome tem que ser IGUAL ao do Code que monta os dados com copy_rules
const base = $('Preparar mensagem/contexto IA').all();

// Pega o texto da resposta da IA, seja qual for o formato do nó
function extrairTexto(r) {
  return (
    r.content?.parts?.[0]?.text ??                  // Gemini (simplificado)
    r.candidates?.[0]?.content?.parts?.[0]?.text ?? // Gemini (completo)
    r.output?.[0]?.content?.[0]?.text ??            // OpenAI (responses)
    r.message?.content ??                           // OpenAI (chat)
    r.text ??
    (typeof r.content === "string" ? r.content : "") ??
    ""
  );
}

// Converte o texto em objeto (remove ```json ... ``` e lixo em volta)
function parseJSON(texto) {
  if (texto && typeof texto === "object") return texto;
  let s = String(texto || "").replace(/```json|```/gi, "").trim();
  const ini = s.indexOf("{");
  const fim = s.lastIndexOf("}");
  if (ini >= 0 && fim > ini) s = s.slice(ini, fim + 1);
  try { return JSON.parse(s); } catch (e) { return null; }
}

// Gera um HTML simples a partir do texto puro (para quando a IA não mandar html)
function textoParaHtml(t) {
  return String(t || "")
    .split(/\n{2,}/)
    .map(p => `<p>${p.replace(/\n/g, "<br>")}</p>`)
    .join("");
}

const brl = (n) =>
  Number(n || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

return $input.all().map((item, i) => {
  const r = item.json;
  const j = base[i]?.json || {};

  const ia = parseJSON(extrairTexto(r));
  const ok = !!(ia && ia.subject && (ia.text_body || ia.html_body));

  // Plano B: se a IA falhar, usa a mensagem estática do MVP
  const subject = ok
    ? String(ia.subject).trim()
    : `Sugestão de investimento: ${j.recomendacao?.produto || "para o seu perfil"}`;

  const text_body = ok
    ? String(ia.text_body || "").trim()
    : `Olá ${j.nome},\n\n${j.mensagem_base || ""}\n\nAtenciosamente,\nSua Equipe de Investimentos`;

  const html_body = ok && ia.html_body
    ? String(ia.html_body).trim()
    : textoParaHtml(text_body);

  return {
    json: {
      ok,
      to: j.email_to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: brl(j.recomendacao?.minimo),
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo,
        origem_texto: ok ? "ia" : "fallback_estatico"
      }
    }
  };
});
